public class RMarketStrategy extends FormRun 
{

}

/// <summary>
///
/// </summary>
private FormDataSource currentCondition_DS()
{
    FormDataSource ret;
    if (ActionConditionTabPage.isActivePage())
        ret = ActionConditionTable_DS;
    else if (OrdersConditionTabPage.isActivePage())
        ret = OrdersConditionTable_DS;
    return ret;
}

private void buildConditionTree()
{
    RMarketStrategyAction strategyAction = RMarketStrategyAction_DS.cursor();

    ConditionTree.deleteAll();

    if (strategyAction.RecId)
    {
        element.addConditionTreeNodes(
            strategyAction.RecId,
            0,
            FormTreeAdd::Root);
    }
}

private TreeItemIdx addConditionTreeNode(
    Common      _record,
    TreeItemIdx _parentNode)
{
    FormTreeItem treeItem;

    if (_record.TableId != tableNum(RMarketConditionGroup)
        && _record.TableId != tableNum(RMarketConditionTable))
    {
        return _parentNode;
    }

    treeItem = new FormTreeItem();

    treeItem.text(element.conditionTreeNodeCaption(_record));
    treeItem.data([_record.TableId, _record.RecId]);

    return ConditionTree.addItem(_parentNode, 0, treeItem);
}

private void addConditionTreeNodes(
    RecId       _actionRecId,
    RefRecId    _parentRecId,
    TreeItemIdx _parentIdx)
{
    RMarketConditionGroup conditionGroup;
    RMarketConditionTable condition;
    FormTreeItem          treeItem;
    TreeItemIdx           itemIdx;
    str                   caption;

    // Root events and nested groups
    while select conditionGroup
    order by conditionGroup.Num
    where conditionGroup.RMarketStrategyActionRecId == _actionRecId
       && conditionGroup.ParentRecId == _parentRecId
    {
        itemIdx = element.addConditionTreeNode(
            conditionGroup,
            _parentIdx);

        // Recursively add nested groups and conditions
        element.addConditionTreeNodes(
            _actionRecId,
            conditionGroup.RecId,
            itemIdx);
    }

    // Leaf conditions of the current group
    if (_parentRecId)
    {
        while select condition
        order by condition.Num
        where condition.Relation ==
                RMarketConditionRelation::RMarketConditionGroup
           && condition.RefRecId == _parentRecId
        {
            itemIdx = element.addConditionTreeNode(
                condition,
                _parentIdx);
        }
    }
}

private str conditionOperandCaption(
    RMarketConditionValueSource _source,
    RMarketIndicatorId          _indicatorId,
    RMarketIndicatorBaseEnum    _candleValue,
    real                        _value,
    RMarketCandleInterval       _interval,
    int                         _shift)
{
    str caption;
    str intervalText;

    switch (_source)
    {
        case RMarketConditionValueSource::Const:
            caption = num2Str(
                _value, 0, 16,
                DecimalSeparator::Dot,
                ThousandSeparator::None);

            // Remove trailing fractional zeroes.
            if (strScan(caption, ".", 1, strLen(caption)))
            {
                while (subStr(caption, strLen(caption), 1) == "0")
                {
                    caption = subStr(caption, 1, strLen(caption) - 1);
                }

                if (subStr(caption, strLen(caption), 1) == ".")
                {
                    caption = subStr(caption, 1, strLen(caption) - 1);
                }
            }

            return caption;

        case RMarketConditionValueSource::Indicator:
            caption = _indicatorId != ""
                ? _indicatorId
                : "Indicator(?)";
            break;

        case RMarketConditionValueSource::Candle:
            caption = _candleValue != RMarketIndicatorBaseEnum::None
                ? enum2Str(_candleValue)
                : "Candle(?)";
            break;

        case RMarketConditionValueSource::LosingTradesInARow:
        case RMarketConditionValueSource::DepositPercentDrawdown:
            return strFmt("%1 [not implemented]", enum2Str(_source));

        default:
            return "Unknown source";
    }

    intervalText = _interval != RMarketCandleInterval::None
        ? strUpr(enum2Str(_interval))
        : "?";

    return strFmt("%1 %2 [%3]", caption, intervalText, _shift);
}

private str conditionTreeNodeCaption(Common _record)
{
    RMarketConditionGroup conditionGroup;
    RMarketConditionTable condition;
    str                   leftOperand, rightOperand;

    switch (_record.TableId)
    {
        case tableNum(RMarketConditionGroup):
            conditionGroup = _record;

            return strFmt(
                "%1 %2 (%3)",
                conditionGroup.ParentRecId ? "▣" : "◆",
                conditionGroup.Name,
                enum2Str(conditionGroup.RMarketConditionOperator));

        case tableNum(RMarketConditionTable):
            condition = _record;

            leftOperand = element.conditionOperandCaption(
                condition.Source,
                condition.IndicatorId,
                condition.CandleValue,
                condition.Value,
                condition.Interval,
                condition.Shift);

            rightOperand = element.conditionOperandCaption(
                condition.SecondSource,
                condition.SecondIndicatorId,
                condition.SecondCandleValue,
                condition.SecondValue,
                condition.SecondInterval,
                condition.SecondShift);

            return strFmt(
                "● %1 %2 %3",
                leftOperand,
                enum2Str(condition.ComparisonType),
                rightOperand);
    }

    return "";
}

private void updateSelectedConditionTreeNode(Common _record)
{
    TreeItemIdx nodeIdx = ConditionTree.getSelection();
    FormTreeItem treeItem;
    container nodeData;
    TableId tableId;
    RecId recId;

    if (!nodeIdx || !_record.RecId)
        return;

    treeItem = ConditionTree.getItem(nodeIdx);

    if (!treeItem)
        return;

    nodeData = treeItem.data();

    if (conLen(nodeData) != 2)
        return;

    [tableId, recId] = nodeData;

    if (tableId != _record.TableId || recId != _record.RecId)
        return;

    treeItem.text(element.conditionTreeNodeCaption(_record));
    ConditionTree.setItem(treeItem);
}

private void createConditionGroup(TreeItemIdx _parentNode = 0)
{
    RMarketStrategyAction strategyAction = RMarketStrategyAction_DS.cursor();

    RMarketConditionGroup conditionGroup;
    RMarketConditionGroup parentGroup;
    RMarketConditionGroup lastGroup;
    RMarketConditionTable lastCondition;

    FormTreeItem    treeItem;
    TreeItemIdx     newItemIdx;
    container       nodeData;
    TableId         tableId;
    RefRecId        parentRecId = 0;
    int             nextNum;

    if (!strategyAction.RecId)
        return;

    // Resolve parent node
    if (_parentNode)
    {
        treeItem = ConditionTree.getItem(_parentNode);

        if (!treeItem)
            return;

        nodeData = treeItem.data();

        if (conLen(nodeData) != 2)
            return;
        [tableId, parentRecId] = nodeData;
        if (tableId != tableNum(RMarketConditionGroup))
            return;

        parentGroup = RMarketConditionGroup::findRecId(parentRecId);

        if (!parentGroup.RecId ||
            parentGroup.RMarketStrategyActionRecId != strategyAction.RecId)
        {
            throw error("Invalid parent condition group.");
        }
    }

    // Find the next sibling number
    select maxof(Num) from lastGroup
    where lastGroup.RMarketStrategyActionRecId
            == strategyAction.RecId
       && lastGroup.ParentRecId == parentRecId;

    nextNum = lastGroup.Num + 1;

    // Nested groups and conditions share the same order
    if (parentRecId)
    {
        select maxof(Num) from lastCondition
            where lastCondition.Relation == RMarketConditionRelation::RMarketConditionGroup
               && lastCondition.RefRecId == parentRecId;

        if (lastCondition.Num >= nextNum)
        nextNum = lastCondition.Num + 1;
    }

    conditionGroup.clear();
    conditionGroup.RMarketStrategyActionRecId = strategyAction.RecId;
    conditionGroup.ParentRecId = parentRecId;
    conditionGroup.Num = nextNum;
    conditionGroup.RMarketConditionOperator = RMarketConditionOperator::And;
    conditionGroup.Name = parentRecId ? strFmt("Group %1", nextNum) : strFmt("Event %1", nextNum);

    if (!conditionGroup.validateWrite())
        return;

    ttsbegin;
    conditionGroup.insert();
    ttscommit;

    RMarketConditionGroup_DS.research(true);
    RMarketConditionGroup_DS.findRecord(conditionGroup);

    // Add only the new node
    newItemIdx = element.addConditionTreeNode(
        conditionGroup,
        _parentNode ? _parentNode : FormTreeAdd::Root);

    // Expand its parent
    if (_parentNode)
    {
        ConditionTree.expand(_parentNode, FormTreeExpand::Expand);
    }

    // Select the newly created node
    ConditionTree.select(newItemIdx);
    element.updateFormDesign();
}

private void createCondition(TreeItemIdx _selectedNode)
{
    RMarketStrategyAction strategyAction = RMarketStrategyAction_DS.cursor();

    RMarketConditionGroup conditionGroup;
    RMarketConditionGroup lastGroup;
    RMarketConditionTable selectedCondition;
    RMarketConditionTable lastCondition;
    RMarketConditionTable condition;

    FormTreeItem    treeItem;
    TreeItemIdx     parentNodeIdx;
    TreeItemIdx     newItemIdx;

    container   nodeData;
    TableId     tableId;
    RecId       recId;
    int         nextNum;

    if (!strategyAction.RecId || !_selectedNode)
        return;

    treeItem = ConditionTree.getItem(_selectedNode);

    if (!treeItem)
        return;

    nodeData = treeItem.data();

    if (conLen(nodeData) != 2)
        return;

    [tableId, recId] = nodeData;

    switch (tableId)
    {
        case tableNum(RMarketConditionGroup):
            // Create a child condition
            conditionGroup = RMarketConditionGroup::findRecId(recId);

            parentNodeIdx = _selectedNode;
            break;

        case tableNum(RMarketConditionTable):
            // Create a sibling condition
            selectedCondition = RMarketConditionTable::findRecId(recId);
            conditionGroup = RMarketConditionGroup::findRecId(selectedCondition.RefRecId);
            if (!conditionGroup.RecId)
                return;

            parentNodeIdx = ConditionTree.getParent(_selectedNode);
            break;

        default:
            return;
    }

    if (!conditionGroup.RecId ||
        conditionGroup.RMarketStrategyActionRecId != strategyAction.RecId ||
        !parentNodeIdx)
    {
        throw error("Invalid parent condition group.");
    }

    // Find next sibling number
    select maxof(Num) from lastGroup
        where lastGroup.RMarketStrategyActionRecId  == strategyAction.RecId
           && lastGroup.ParentRecId                 == conditionGroup.RecId;

    select maxof(Num) from lastCondition
        where lastCondition.Relation == RMarketConditionRelation::RMarketConditionGroup
           && lastCondition.RefRecId == conditionGroup.RecId;

    nextNum = lastGroup.Num + 1;

    if (lastCondition.Num >= nextNum)
        nextNum = lastCondition.Num + 1;

    // Initialize the condition
    condition.clear();
    condition.initValue();
    condition.Relation       = RMarketConditionRelation::RMarketConditionGroup;
    condition.RefRecId       = conditionGroup.RecId;
    condition.Num            = nextNum;
    condition.Source         = RMarketConditionValueSource::Const;
    condition.SecondSource   = RMarketConditionValueSource::Const;
    // 0 < 0 is FALSE until configured
    condition.ComparisonType = RMarketConditionComparisonType::Less;
    condition.Interval       = RMarketStrategy.Interval;
    condition.SecondInterval = RMarketStrategy.Interval;

    if (!condition.validateWrite())
        return;

    ttsbegin;
    condition.insert();
    ttscommit;

    // Refresh the condition editor
    RMarketConditionGroup_DS.findRecord(conditionGroup);
    RMarketConditionTable_DS.research(true);
    RMarketConditionTable_DS.findRecord(condition);

    // Add only the new leaf
    newItemIdx = element.addConditionTreeNode(condition, parentNodeIdx);

    ConditionTree.expand(parentNodeIdx, FormTreeExpand::Expand);
    ConditionTree.select(newItemIdx);
    element.updateFormDesign();
}

private container selectedNodeData(FormTreeControl _tree)
{
    FormTreeItem treeItem;
    TreeItemIdx nodeIdx;

    if (!_tree)
        return [0, 0];

    nodeIdx = _tree.getSelection();

    if (!nodeIdx)
        return [0, 0];

    treeItem = _tree.getItem(nodeIdx);

    return treeItem ? treeItem.data() : [0, 0];
}

private void updateFormDesign()
{
    TableId tableId;
    RecId recId;
    [tableId, recId]        = element.selectedNodeData(ConditionTree);
    boolean groupSelected   = tableId == tableNum(RMarketConditionGroup);
    boolean leafSelected    = tableId == tableNum(RMarketConditionTable);
    boolean nodeSelected    = groupSelected || leafSelected;
    boolean actionSelected  = RMarketStrategyAction_DS.cursor().RecId != 0;

    NodeNewEventButton.enabled(actionSelected); 
    NodeNewGroupButton.enabled(actionSelected && groupSelected); 
    NodeNewConditionButton.enabled(actionSelected && nodeSelected);
    NodeDeleteButton.enabled(nodeSelected && false); // Node in tree selected and hasn't any child
    NodeUpButton.enabled(false); // Node has Num > 1
    NodeDownButton.enabled(false); // Node has Num < max(Num)

    // any changes of elements visibility or enablity must be here
    // Node settings
    GroupSettingsGroup.visible(groupSelected);
    ConditionSettingsGroup.visible(leafSelected);
}

