}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketStrategyAction action;

    super(_append);

    select maxof(Num) from action
        where action.StrategyId == RMarketStrategy.StrategyId;

    RMarketStrategyAction record = this.cursor();
    //record.StrategyId = RMarketStrategy.StrategyId;
    record.Num   = action.Num + 1;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret = super();

    element.buildConditionTree();
    element.updateFormDesign();

    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketConditionTable condition;

    super(_append);

    select maxof(Num) from condition
        where condition.RefRecId == ActionConditionTable.RefRecId;

    RMarketConditionTable record = this.cursor();
    //record.RefRecId = RMarketStrategyAction.RecId;
    record.Num   = condition.Num + 1;
    record.Relation = RMarketConditionRelation::RMarketStrategyAction;
    record.Interval = RMarketStrategy.Interval;
    record.SecondInterval = RMarketStrategy.Interval;
}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketConditionTable condition;

    super(_append);

    select maxof(Num) from condition
        where condition.RefRecId == OrdersConditionTable.RefRecId;

    RMarketConditionTable record = this.cursor();
    //record.RefRecId = RMarketStrategyAction.RecId;
    record.Num   = condition.Num + 1;
    record.Relation = RMarketConditionRelation::RMarketStrategyOrders;
    record.Interval = RMarketStrategy.Interval;
    //record.SecondInterval = RMarketStrategy.Interval;
}

