/// <summary>
///
/// </summary>
/// <param name = "_OldItem"></param>
/// <param name = "_NewItem"></param>
/// <param name = "_how"></param>
public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
{
    container nodeData;
    TableId tableId;
    RecId recId;
    RMarketConditionGroup conditionGroup;
    RMarketConditionTable condition;

    super(_oldItem, _newItem, _how);

    if (_newItem)
    {
        nodeData = _newItem.data();

        if (conLen(nodeData) == 2)
        {
            [tableId, recId] = nodeData;

            switch(tableId)
            {
                case tableNum(RMarketConditionGroup):
                    conditionGroup = RMarketConditionGroup::findRecId(recId);
                    if (conditionGroup.RecId)
                    {
                        RMarketConditionGroup_DS.findRecord(conditionGroup);
                    }
                    break;

                case tableNum(RMarketConditionTable):
                    condition = RMarketConditionTable::findRecId(recId);
                    conditionGroup = RMarketConditionGroup::findRecId(condition.RefRecId);
                    if (conditionGroup.RecId)
                    {
                        RMarketConditionGroup_DS.findRecord(conditionGroup);
                        if (condition.RecId)
                        {
                            RMarketConditionTable_DS.findRecord(condition);
                        }
                    }
                    break;
            }
        }
    }

    element.updateFormDesign();
}

